'use client'

import { useState } from 'react'
import {
  useReactTable,
  getCoreRowModel,
  getPaginationRowModel,
  ColumnDef,
  flexRender,
} from '@tanstack/react-table'
import Image from 'next/image'
import { Trash2, Edit } from 'lucide-react'
import { useRouter } from 'next/navigation'
import {
  useGetPendingProducts,
  useDeleteProduct,
} from '@/lib/handleAllGetRequests'
import ErrorState from '@/components/reusable/ErrorState'
import TableSkeleton from '@/components/reusable/TableSkeleton'
import { Product } from '@/../types/products'
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'

export default function PendingProductsTable() {
  const router = useRouter()
  const { data, isLoading, isError } = useGetPendingProducts()
  const deleteProduct = useDeleteProduct()

  const [deleteId, setDeleteId] = useState<string | null>(null)

  const products: Product[] = data?.data || []

  const handleConfirmDelete = () => {
    if (deleteId) {
      deleteProduct.mutate(deleteId)
      setDeleteId(null)
    }
  }

  const columns: ColumnDef<Product>[] = [
    {
      header: 'Product Name',
      cell: ({ row }) => (
        <div className="flex items-center gap-2">
          <div className="w-[100px] h-[60px] relative">
            <Image
              src={row.original.images?.[0] || '/images/placeholder.png'}
              alt={row.original.title}
              fill
              className="rounded-lg object-cover"
            />
          </div>
          <span className="text-lg font-medium">{row.original.title}</span>
        </div>
      ),
    },
    { header: 'Category', accessorFn: (row) => row.category?.name || 'N/A' },
    { header: 'Price', accessorFn: (row) => `$${row.unitPrice}` },
    { header: 'Quantity', accessorKey: 'quantity' },
    { header: 'Status', accessorKey: 'status' },
    {
      header: 'Date',
      accessorFn: (row) =>
        new Date(row.createdAt).toLocaleDateString('en-US', {
          month: '2-digit',
          day: '2-digit',
          year: 'numeric',
        }) +
        '\n' +
        new Date(row.createdAt).toLocaleTimeString('en-US', {
          hour: '2-digit',
          minute: '2-digit',
          hour12: true,
        }),
    },
    {
      header: 'Action',
      cell: ({ row }) => (
        <div className="flex items-center gap-3">
          {/* Delete */}
          <button
            onClick={() => setDeleteId(row.original._id)}
            className="text-[#595959] hover:text-[#595959]/90 cursor-pointer"
          >
            <Trash2 size={18} />
          </button>

          {/* Edit */}
          <button
            onClick={() =>
              router.push(`/seller-dashboard/edit-product/${row.original._id}`)
            }
            className="text-[#595959] hover:text-[#595959]/90 cursor-pointer"
          >
            <Edit size={18} />
          </button>
        </div>
      ),
    },
  ]

  const table = useReactTable({
    data: products,
    columns,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    initialState: { pagination: { pageSize: 6 } },
  })

  if (isLoading) return <TableSkeleton />
  if (isError)
    return <ErrorState message="Failed to load the pending products" />

  return (
    <div className="bg-transparent border rounded-lg">
      <table className="w-full text-left">
        <thead className="bg-transparent">
          {table.getHeaderGroups().map((headerGroup) => (
            <tr key={headerGroup.id}>
              {headerGroup.headers.map((header) => (
                <th
                  key={header.id}
                  className="px-4 py-3 text-sm font-medium text-[#272727]"
                >
                  {flexRender(
                    header.column.columnDef.header,
                    header.getContext()
                  )}
                </th>
              ))}
            </tr>
          ))}
        </thead>
        <tbody>
          {table.getRowModel().rows.map((row) => (
            <tr key={row.id} className="border-t">
              {row.getVisibleCells().map((cell) => (
                <td key={cell.id} className="px-4 py-3 text-sm text-[#595959]">
                  {flexRender(cell.column.columnDef.cell, cell.getContext())}
                </td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>

      {/* Pagination */}
      <div className="flex items-center justify-between bg-white border-t px-8 py-3 text-sm">
        <div className="text-[#707070] text-base font-medium">
          Showing{' '}
          {table.getState().pagination.pageIndex *
            table.getState().pagination.pageSize +
            1}{' '}
          to{' '}
          {Math.min(
            (table.getState().pagination.pageIndex + 1) *
              table.getState().pagination.pageSize,
            products.length
          )}{' '}
          of {products.length} results
        </div>

        {/* Prev / Next */}
        <div className="flex items-center gap-2">
          <button
            onClick={() => table.previousPage()}
            disabled={!table.getCanPreviousPage()}
            className={`w-[40px] h-[40px] rounded-md text-white text-sm font-medium ${
              table.getCanPreviousPage()
                ? 'bg-[#797068]'
                : 'bg-gray-300 cursor-not-allowed'
            }`}
          >
            {'<'}
          </button>
          {Array.from({ length: table.getPageCount() }, (_, i) => {
            const isActive = table.getState().pagination.pageIndex === i
            return (
              <button
                key={i}
                onClick={() => table.setPageIndex(i)}
                className={`w-[40px] h-[40px] rounded-md text-white text-sm font-medium ${
                  isActive ? 'bg-[#797068]' : 'bg-gray-300'
                }`}
              >
                {i + 1}
              </button>
            )
          })}
          <button
            onClick={() => table.nextPage()}
            disabled={!table.getCanNextPage()}
            className={`w-[40px] h-[40px] rounded-md text-white text-sm font-medium ${
              table.getCanNextPage()
                ? 'bg-[#797068]'
                : 'bg-gray-300 cursor-not-allowed'
            }`}
          >
            {'>'}
          </button>
        </div>
      </div>

      {/* Delete Confirm Dialog */}

      <Dialog open={!!deleteId} onOpenChange={() => setDeleteId(null)}>
        <DialogContent className="w-[400px]">
          <DialogHeader>
            <DialogTitle>Delete Product</DialogTitle>
          </DialogHeader>
          <p>Are you sure you want to delete this product?</p>
          <DialogFooter className="flex justify-center gap-3 mt-4">
            <Button variant="outline" onClick={() => setDeleteId(null)}>
              Cancel
            </Button>
            <Button variant="default" onClick={handleConfirmDelete}>
              Yes, Delete
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}
